CREATE TABLE emprestimo (
  id_emprestimo INTEGER PRIMARY KEY,
  id_leitor INTEGER NOT NULL REFERENCES leitor(id_leitor),
  id_exemplar INTEGER NOT NULL REFERENCES exemplar(id_exemplar),
  retirada DATE NOT NULL,
  prevista DATE NOT NULL CHECK (prevista >= retirada),
  devolucao DATE CHECK (devolucao >= retirada)
);
CREATE UNIQUE INDEX um_ativo_por_exemplar
ON emprestimo(id_exemplar) WHERE devolucao IS NULL;
